    public void applyDiscount(String orderId, String percent) {
        long rate = parseBasisPoints(percent);
        Order order = orders.get(orderId);
        Money total = order.total();
        // Half up: add half of the divisor (5000 of 10000) before the integer division.
        long discount = (Math.multiplyExact(total.minorUnits(), rate) + 5000) / 10000;
        order.changeTotal(total.minus(new Money(discount, total.currency())));
    }

    /**
     * Converts text such as "12.5" or "12.50" into whole basis points (1250), by hand.
     * Accepts digits with at most two decimal places, from 0 to 100 percent.
     */
    static long parseBasisPoints(String text) {
        String s = text == null ? "" : text.trim();
        int dot = s.indexOf('.');
        String whole = dot < 0 ? s : s.substring(0, dot);
        String fraction = dot < 0 ? "" : s.substring(dot + 1);
        if (whole.isEmpty() && fraction.isEmpty() || fraction.length() > 2) {
            throw invalidPercent(text);
        }
        long points = 0;
        for (char c : whole.toCharArray()) {
            points = points * 10 + digit(c, text);
            if (points > 100) {
                throw invalidPercent(text);
            }
        }
        long hundredths = 0;
        for (char c : fraction.toCharArray()) {
            hundredths = hundredths * 10 + digit(c, text);
        }
        if (fraction.length() == 1) {
            hundredths *= 10;
        }
        long rate = points * 10000 + hundredths * 100;
        if (rate > 10000) {
            throw invalidPercent(text);
        }
        return rate;
    }

    private static long digit(char c, String text) {
        if (c < '0' || c > '9') {
            throw invalidPercent(text);
        }
        return c - '0';
    }

    private static ShopProblem invalidPercent(String text) {
        return new ShopProblem("invalid-percent", "Not a percentage from 0 to 100 with at most two decimals: " + text);
    }

