import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.platform.ShopProblem;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class OrderServiceDiscountTest {

    private final OrderService orders = new OrderService(new OrderRepository());

    @Test
    void halfACentOfPercentRoundsHalfUp() {
        String id = orders.place("c-1", Money.pln(100), Instant.parse("2026-10-01T10:00:00Z"));

        orders.applyDiscount(id, "0.5");

        assertEquals(Money.pln(99), orders.summary(id).total());
    }

    @Test
    void discountIsTakenFromTheTotal() {
        String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

        orders.applyDiscount(id, "12.5");

        assertEquals(Money.pln(875), orders.summary(id).total());
    }

    @Test
    void discountBelowHalfIsRoundedDown() {
        String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

        orders.applyDiscount(id, "0.04");

        assertEquals(Money.pln(1000), orders.summary(id).total());
    }

    @Test
    void parsesPercentTextIntoBasisPoints() {
        assertEquals(1250, OrderService.parseBasisPoints("12.5"));
        assertEquals(1250, OrderService.parseBasisPoints("12.50"));
        assertEquals(1205, OrderService.parseBasisPoints("12.05"));
        assertEquals(1200, OrderService.parseBasisPoints("12"));
        assertEquals(50, OrderService.parseBasisPoints(" 0.5 "));
        assertEquals(10000, OrderService.parseBasisPoints("100"));
        assertEquals(0, OrderService.parseBasisPoints("0"));
    }

    @Test
    void rejectsPercentTextThatIsNotAPercentage() {
        for (String text : new String[] {"", " ", ".", "-5", "+5", "12,5", "1e2", "abc", "12.505", "100.01", "101", "1000000000000000000000"}) {
            ShopProblem problem = assertThrows(ShopProblem.class, () -> OrderService.parseBasisPoints(text), text);
            assertEquals("invalid-percent", problem.code());
        }
        assertThrows(ShopProblem.class, () -> OrderService.parseBasisPoints(null));
    }
}
}
